-- Wypożyczalnia sprzętu elektronicznego: struktura bazy (PostgreSQL).
-- Zgodne z docs/schema.dbml. Warunki CHECK dochodzą w osobnym kroku.
--
-- Klucze główne: GENERATED BY DEFAULT AS IDENTITY, a nie ALWAYS,
-- bo sql/02_data.sql wstawia rekordy z jawnymi id.

BEGIN;

-- ===== Usunięcie poprzedniej wersji =====

DROP TABLE IF EXISTS payments, rental_items, rentals, equipment, customers;
DROP TYPE IF EXISTS equipment_status, payment_method, payment_type;

-- ===== Typy wyliczeniowe =====

CREATE TYPE equipment_status AS ENUM ('available', 'rented', 'maintenance', 'retired');
CREATE TYPE payment_method   AS ENUM ('cash', 'card', 'bank_transfer', 'blik');
CREATE TYPE payment_type     AS ENUM ('rental_fee', 'deposit', 'deposit_refund', 'penalty');

-- ===== Tabele =====

-- Klienci: osoby prywatne i firmy
CREATE TABLE customers (
    customer_id       integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    first_name        varchar(50)  NOT NULL,
    last_name         varchar(50)  NOT NULL,
    address           varchar(200) NOT NULL,
    phone_number      varchar(20)  NOT NULL,
    email             varchar(100) NOT NULL UNIQUE,
    nip               varchar(10)  UNIQUE,          -- tylko klienci biznesowi
    registration_date date         NOT NULL DEFAULT CURRENT_DATE
);

-- Sprzęt: jeden rekord = jeden egzemplarz
CREATE TABLE equipment (
    equipment_id  integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name          varchar(100)     NOT NULL,
    category      varchar(50)      NOT NULL,
    manufacturer  varchar(50)      NOT NULL,
    serial_number varchar(50)      NOT NULL UNIQUE,
    description   text,
    daily_rate    numeric(10,2)    NOT NULL,
    deposit       numeric(10,2)    NOT NULL DEFAULT 0,
    status        equipment_status NOT NULL DEFAULT 'available',
    purchase_date date             NOT NULL
);

-- Wypożyczenia: pakiet, może zawierać wiele egzemplarzy
CREATE TABLE rentals (
    rental_id    integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    customer_id  integer      NOT NULL
                 REFERENCES customers (customer_id) ON DELETE RESTRICT,
    rental_date  timestamp(0) NOT NULL DEFAULT now(),
    due_date     date         NOT NULL,
    return_date  timestamp(0),                      -- NULL, dopóki sprzęt nie wróci
    is_cancelled boolean      NOT NULL DEFAULT false
);

-- Pozycje wypożyczenia: tabela łącząca rentals i equipment (M:N)
CREATE TABLE rental_items (
    rental_item_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    rental_id      integer       NOT NULL
                   REFERENCES rentals (rental_id) ON DELETE CASCADE,
    equipment_id   integer       NOT NULL
                   REFERENCES equipment (equipment_id) ON DELETE RESTRICT,
    daily_rate     numeric(10,2) NOT NULL,          -- stawka z chwili wypożyczenia
    deposit        numeric(10,2) NOT NULL DEFAULT 0, -- kaucja z chwili wypożyczenia
    penalty        numeric(10,2),                   -- naliczana przy zwrocie
    return_notes   varchar(500),
    is_cancelled   boolean       NOT NULL DEFAULT false,

    CONSTRAINT rental_items_rental_equipment_key UNIQUE (rental_id, equipment_id)
);

-- Płatności: opłaty, kaucje, zwroty kaucji, kary
CREATE TABLE payments (
    payment_id   integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    rental_id    integer        NOT NULL
                 REFERENCES rentals (rental_id) ON DELETE RESTRICT,
    payment_date timestamp(0)   NOT NULL DEFAULT now(),
    amount       numeric(10,2)  NOT NULL,           -- zawsze > 0, kierunek wynika z type
    method       payment_method NOT NULL,
    type         payment_type   NOT NULL
);

COMMIT;
